use std::path::Path;

/// Minimal stub written if `../dist/index.html` is missing — keeps the Tauri
/// build macro happy for users running `cargo install` without `npm run build`.
/// Kept inline (not `include_str!`) so it doesn't itself require the file to exist.
const DIST_STUB: &str = r#"<!doctype html>
<!-- Generated by build.rs because dist/index.html was missing. dalzzack
     uses an inline data: URL landing at runtime (see src/app.rs), so this
     file's contents are not displayed; only its existence is needed for
     tauri::generate_context!() to validate frontendDist at compile time. -->
<html lang="en"><head><meta charset="UTF-8"><title>dalzzack</title></head>
<body><div id="root"></div></body></html>
"#;

/// Make `cargo test` runnable on Windows.
///
/// Something in the GUI dependency tree statically imports
/// `comctl32!TaskDialogIndirect`, which exists only in the side-by-side v6
/// assembly. The real binary gets that dependency from the manifest
/// `tauri_build` embeds; test harness binaries get no manifest, so they load
/// comctl32 v5.82, the import doesn't resolve, and the process dies at load
/// time with `STATUS_ENTRYPOINT_NOT_FOUND` (0xc0000139) before a single test
/// runs. Declaring the same dependency for test targets fixes it.
#[cfg(target_os = "windows")]
fn enable_windows_tests() {
    // `rustc-link-arg-tests` covers only `tests/` targets, not the `--lib`
    // unit-test harness, so this has to be the blanket form.
    println!(
        "cargo::rustc-link-arg=/MANIFESTDEPENDENCY:type='win32' \
         name='Microsoft.Windows.Common-Controls' version='6.0.0.0' \
         processorArchitecture='*' publicKeyToken='6595b64144ccf1df' language='*'"
    );
}

#[cfg(not(target_os = "windows"))]
fn enable_windows_tests() {}

fn main() {
    enable_windows_tests();

    // tauri::generate_context!() requires the path in tauri.conf.json's
    // `frontendDist` to exist at compile time. We commit a stub at ../dist/
    // index.html so a fresh `cargo install --git` works without running npm.
    // This branch only fires if someone (or `cargo package`) stripped the stub.
    let dist_index = Path::new("../dist/index.html");
    if !dist_index.exists() {
        if let Some(parent) = dist_index.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let _ = std::fs::write(dist_index, DIST_STUB);
    }

    tauri_build::build()
}
